/// The severity to relate to the assessments generated by this Recommendation.
enum SecurityIssue {
  valueVulnerability("Vulnerability"),
  valueExcessivePermissions("ExcessivePermissions"),
  valueAnonymousAccess("AnonymousAccess"),
  valueNetworkExposure("NetworkExposure"),
  valueTrafficEncryption("TrafficEncryption"),
  valueBestPractices("BestPractices");

  const SecurityIssue(this.value);
  final String value;

  static SecurityIssue fromValue(String value) {
    for (final item in SecurityIssue.values) {
      if (item.value == value) {
        return item;
      }
    }
    throw ArgumentError('Unknown SecurityIssue value: $value');
  }
}

